        image[r as usize][c as usize] = color;
        Self::dfs(image, r + 1, c, orig, color, m, n);
        Self::dfs(image, r - 1, c, orig, color, m, n);
        Self::dfs(image, r, c + 1, orig, color, m, n);
        Self::dfs(image, r, c - 1, orig, color, m, n);
